mapper.insert:
INSERT INTO member_profile_photo_retirement_manifest (
    stored_file_id, storage_scope_code, storage_key, retirement_status_code
) VALUES (
    #{storedFileId}, #{storageScope}, #{storageKey}, #{status}
)

mapper.update:
UPDATE member_profile_photo_retirement_manifest
SET retirement_status_code = 'DELETED',
    attempt_count = attempt_count + 1,
    failure_reason = NULL,
    completed_dttm = #{completedDttm}
WHERE member_profile_photo_retirement_manifest_id = #{manifestId}

UPDATE member_profile_photo_retirement_manifest
SET retirement_status_code = 'FAILED',
    attempt_count = attempt_count + 1,
    failure_reason = #{failureReason}
WHERE member_profile_photo_retirement_manifest_id = #{manifestId}
